const b = $input.first().json.body || $input.first().json || {};
const platform = String(b.platform || 'discord').toLowerCase();
const target = String(b.target || '');
const message = String(b.message || '');
const brand = $env.BRAND_NAME || 'Tradesejon';
if (!target || !message) return [{ json: { ok: false, delivered: false, error: 'Missing target or message payload' } }];

if (platform === 'discord') {
  const token = $env.DISCORD_BOT_TOKEN;
  if (!token) return [{ json: { ok: false, delivered: false, error: 'DISCORD_BOT_TOKEN not configured' } }];
  const dmRes = await fetch('https://discord.com/api/v10/users/@me/channels', {
    method: 'POST', headers: { 'Authorization': `Bot ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ recipient_id: target })
  });
  const dmData = await dmRes.json();
  if (!dmRes.ok || !dmData.id) return [{ json: { ok: false, delivered: false, error: 'Discord DM open failed', details: dmData } }];
  const msgRes = await fetch(`https://discord.com/api/v10/channels/${dmData.id}/messages`, {
    method: 'POST', headers: { 'Authorization': `Bot ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ content: message })
  });
