// 2. Probe whether individual webhook is published; fall back gracefully to /webhook/tradesejon-unified if unpublished
async function resolveTargetWebhookPath(preferredPath) {
  try {
    const probe = await fetch(`${n8nInternal}/webhook/${preferredPath}`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ _probe: true })
    });
    if (probe.status !== 404) return preferredPath;
  } catch (e) {}
  return 'tradesejon-unified';
}

for (const [label, tok, preferredPath] of [
  ['CEO_BOT', $env.TELEGRAM_CEO_BOT_TOKEN, 'tradesejon-ceo'],
  ['PR_BOT', $env.TELEGRAM_PR_BOT_TOKEN, 'tradesejon-pr'],
  ['TRADER_BOT', $env.TELEGRAM_TRADER_BOT_TOKEN, 'tradesejon-trader']
]) {
  if (!tok || !baseUrl) {
    summary.telegram.push({ bot: label, ok: false, error: 'Missing token or WEBHOOK_URL' });
    continue;
  }
  const resolvedPath = await resolveTargetWebhookPath(preferredPath);
  try {
    const res = await fetch(`https://api.telegram.org/bot${tok}/setWebhook?url=${encodeURIComponent(baseUrl + '/webhook/' + resolvedPath)}`).then(r => r.json());
    summary.telegram.push({ bot: label, ok: Boolean(res.ok), bound_path: resolvedPath, description: res.description });
  } catch (e) {
    summary.telegram.push({ bot: label, ok: false, error: e.message });
  }
}

